using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Configuration.AddEnvironmentVariables();

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddSingleton(new OpenAIClient(apiKey));
builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId));
builder.Services.AddSingleton<Notebook>();
builder.Services.AddHostedService<ResearchWorker>();

var host = builder.Build();
await host.RunAsync();

// ---------------------------------------------------------------------------
// Hosted service that runs the agent loop
// ---------------------------------------------------------------------------
sealed class ResearchWorker(
    IChatClient chatClient,
    Notebook notebook,
    IHostApplicationLifetime lifetime,
    ILoggerFactory loggerFactory) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        Console.WriteLine("╔══════════════════════════════════════════════╗");
        Console.WriteLine("║        🔍  AI Research Agent                ║");
