using System;
using System.Linq;
using System.Reflection;

// Check MEAI abstractions
var meaiAsm = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.extensions.ai.abstractions/10.6.0/lib/net10.0/Microsoft.Extensions.AI.Abstractions.dll");

// Find AIFunction related types
foreach(var t in meaiAsm.GetExportedTypes().Where(t => t.Name.Contains("AIFunction") || t.Name.Contains("McpTool")).OrderBy(t => t.Name))
{
    Console.WriteLine($"\n{t.FullName} (abstract={t.IsAbstract}, sealed={t.IsSealed}):");
    foreach(var c in t.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  ctor({string.Join(", ", c.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
    foreach(var m in t.GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  static {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => p.ParameterType.Name + " " + p.Name))})");
    foreach(var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  {p.PropertyType.Name} {p.Name} {{ {(p.CanRead?"get;":"")} {(p.CanWrite?"set;":"")} }}");
}
CSHARP
dotnet run --project /tmp/reflector -- dummy 2>&1

