35. // ---------------------------------------------------------------------------
36. // Hosted service that runs the agent loop
37. // ---------------------------------------------------------------------------
38. sealed class ResearchWorker(
39.     IChatClient chatClient,
40.     Notebook notebook,
41.     IHostApplicationLifetime lifetime,
42.     ILoggerFactory loggerFactory) : BackgroundService
43. {
44.     protected override async Task ExecuteAsync(CancellationToken stoppingToken)
45.     {
46.         Console.WriteLine("╔══════════════════════════════════════════════╗");
47.         Console.WriteLine("║        🔍  AI Research Agent                ║");
48.         Console.WriteLine("║  Type a topic to research, or 'quit' to exit║");
49.         Console.WriteLine("╚══════════════════════════════════════════════╝");
50. 
51.         var researchTools = new ResearchTools(notebook);
52.         var tools = new List<AITool>
53.         {
54.             AIFunctionFactory.Create(researchTools.WebSearchAsync,
55.                 name: "web_search",
56.                 description: "Search the web for information on a query. Returns results with titles, snippets, and URLs."),
57.             AIFunctionFactory.Create(researchTools.SaveNote,
58.                 name: "save_note",
59.                 description: "Save a research note with a title and content. Use to record key findings during research."),
60.             AIFunctionFactory.Create(researchTools.GetNotes,
61.                 name: "get_notes",
62.                 description: "Retrieve all saved research notes collected so far."),
63.         };
64.         var agent = new ChatClientAgent(
65.             chatClient,
66.             instructions: """
67.                 You are a research agent. When given a topic:
68.                 1. Use the web_search tool to find relevant information (perform multiple searches with varied queries).
69.                 2. Use the save_note tool to record key findings as you go.
70.                 3. Use the get_notes tool to review what you've collected.
71.                 4. After gathering enough information, provide a comprehensive summary.
72.                 Be thorough — search from multiple angles before summarizing.
