 sealed class ResearchTools(Notebook notebook)
 {
     public async Task<string> WebSearchAsync(
         [Description("The search query string")] string query,
         [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
     {
         Console.WriteLine($"  🌐 Searching: \"{query}\"");

         maxResults = Math.Clamp(maxResults, 1, 10);

         try
         {
             using var http = new HttpClient();
             http.DefaultRequestHeaders.UserAgent.ParseAdd(
                 "ResearchAgent/1.0 (educational project)");

             // Use DuckDuckGo Instant Answer API (no key required)
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var json = await http.GetStringAsync(url);

             using var doc = JsonDocument.Parse(json);
             var root = doc.RootElement;
             var results = new List<object>();

             // Abstract (main answer)
             var abstractText = root.GetProperty("Abstract").GetString();
             var abstractUrl = root.GetProperty("AbstractURL").GetString();
             var abstractSource = root.GetProperty("AbstractSource").GetString();
             if (!string.IsNullOrEmpty(abstractText))
             {
                 results.Add(new { title = $"Summary from {abstractSource}", snippet = abstractText, url = abstractUrl });
             }

             // Related topics
             if (root.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
             {
                 foreach (var topic in topics.EnumerateArray())
                 {
                     if (results.Count >= maxResults) break;
                     var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                     var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                     if (!string.IsNullOrEmpty(text))
                     {
                         results.Add(new { title = text.Length > 80 ? text[..80] + "..." : text, snippet = text, url = firstUrl ?? "" });
                     }
                 }
             }

             // Answer field
             var answer = root.GetProperty("Answer").GetString();
             if (!string.IsNullOrEmpty(answer) && results.Count == 0)
             {
                 results.Add(new { title = "Direct Answer", snippet = answer, url = "" });
             }

             if (results.Count == 0)
             {
                 return JsonSerializer.Serialize(new { message = $"No results found for '{query}'. Try rephrasing." });
             }

             Console.WriteLine($"  ✅ Found {results.Count} result(s)");
             return JsonSerializer.Serialize(new { query, resultCount = results.Count, results });
         }
         catch (Exception ex)
         {
             return JsonSerializer.Serialize(new { error = $"Search failed: {ex.Message}", query });
         }
     }

