         Console.WriteLine("╔══════════════════════════════════════════════╗");
         Console.WriteLine("║        🔍  AI Research Agent                ║");
         Console.WriteLine("║  Type a topic to research, or 'quit' to exit║");
         Console.WriteLine("╚══════════════════════════════════════════════╝");

         var researchTools = new ResearchTools(notebook);
         var tools = new List<AITool>
         {
             AIFunctionFactory.Create(researchTools.WebSearchAsync,
                 name: "web_search",
                 description: "Search the web for information on a query. Returns results with titles, snippets, and URLs."),
             AIFunctionFactory.Create(researchTools.SaveNote,
                 name: "save_note",
                 description: "Save a research note with a title and content. Use to record key findings during research."),
             AIFunctionFactory.Create(researchTools.GetNotes,
                 name: "get_notes",
                 description: "Retrieve all saved research notes collected so far."),
         };
         var agent = new ChatClientAgent(
             chatClient,
             instructions: """
                 You are a research agent. When given a topic:
                 1. Use the web_search tool to find relevant information (perform multiple searches with varied queries).
                 2. Use the save_note tool to record key findings as you go.
                 3. Use the get_notes tool to review what you've collected.
                 4. After gathering enough information, provide a comprehensive summary.
                 Be thorough — search from multiple angles before summarizing.
                 """,
             name: "ResearchAgent",
             description: "An agent that researches topics using web search and note-taking tools.",
             tools: tools,
             loggerFactory: loggerFactory);

         while (!stoppingToken.IsCancellationRequested)
         {
             Console.Write("\n📝 Research topic: ");
             var topic = Console.ReadLine();
             if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
                 break;

             notebook.Clear();
             Console.WriteLine($"\n🔎 Researching: {topic}\n");

             try
             {
                 var session = await agent.CreateSessionAsync(
                     Guid.NewGuid().ToString(), stoppingToken);

                 var runOptions = new ChatClientAgentRunOptions
                 {
                     ChatOptions = new ChatOptions
                     {
                         Temperature = 0f,
                         MaxOutputTokens = 4096,
                     },
                 };

                 var response = await agent.RunAsync(
                     $"Research the following topic and provide a summary: {topic}",
                     session,
                     runOptions,
                     stoppingToken);

                 Console.WriteLine("═══════════════════  RESULTS  ═══════════════════");
                 Console.WriteLine(response.Text);
                 Console.WriteLine("═════════════════════════════════════════════════");

                 if (notebook.Notes.Count > 0)
                 {
                     Console.WriteLine($"\n📓 {notebook.Notes.Count} note(s) saved during research.");
                 }
             }
             catch (Exception ex)
             {
                 Console.WriteLine($"❌ Error: {ex.Message}");
             }
         }

         lifetime.StopApplication();
     }
 }

 // ---------------------------------------------------------------------------
 // Tools exposed to the agent
 // ---------------------------------------------------------------------------
 sealed class ResearchTools(Notebook notebook)
 {
     public async Task<string> WebSearchAsync(
         [Description("The search query string")] string query,
         [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
     {
         Console.WriteLine($"  🌐 Searching: \"{query}\"");

         maxResults = Math.Clamp(maxResults, 1, 10);

         try
         {
             using var http = new HttpClient();
             http.DefaultRequestHeaders.UserAgent.ParseAdd(
                 "ResearchAgent/1.0 (educational project)");

             // Use DuckDuckGo Instant Answer API (no key required)
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var json = await http.GetStringAsync(url);

             using var doc = JsonDocument.Parse(json);
             var root = doc.RootElement;
             var results = new List<object>();

             // Abstract (main answer)
             var abstractText = root.GetProperty("Abstract").GetString();
             var abstractUrl = root.GetProperty("AbstractURL").GetString();
             var abstractSource = root.GetProperty("AbstractSource").GetString();
             if (!string.IsNullOrEmpty(abstractText))
             {
                 results.Add(new { title = $"Summary from {abstractSource}", snippet = abstractText, url = abstractUrl });
             }

             // Related topics
             if (root.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
             {
                 foreach (var topic in topics.EnumerateArray())
                 {
                     if (results.Count >= maxResults) break;
                     var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                     var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                     if (!string.IsNullOrEmpty(text))
                     {
                         results.Add(new { title = text.Length > 80 ? text[..80] + "..." : text, snippet = text, url = firstUrl ?? "" });
                     }
                 }
             }

             // Answer field
             var answer = root.GetProperty("Answer").GetString();
             if (!string.IsNullOrEmpty(answer) && results.Count == 0)
             {
                 results.Add(new { title = "Direct Answer", snippet = answer, url = "" });
             }

             if (results.Count == 0)
             {
                 return JsonSerializer.Serialize(new { message = $"No results found for '{query}'. Try rephrasing." });
             }

             Console.WriteLine($"  ✅ Found {results.Count} result(s)");
             return JsonSerializer.Serialize(new { query, resultCount = results.Count, results });
         }
         catch (Exception ex)
         {
             return JsonSerializer.Serialize(new { error = $"Search failed: {ex.Message}", query });
         }
     }

     public string SaveNote(
         [Description("Short title for the note")] string title,
         [Description("The content/finding to save")] string content)
     {
         notebook.Add(title, content);
         Console.WriteLine($"  📝 Note saved: \"{title}\"");
         return JsonSerializer.Serialize(new { status = "saved", title, totalNotes = notebook.Notes.Count });
     }

     public string GetNotes()
     {
         if (notebook.Notes.Count == 0)
             return JsonSerializer.Serialize(new { message = "No notes saved yet." });

         Console.WriteLine($"  📓 Reviewing {notebook.Notes.Count} note(s)");
         return JsonSerializer.Serialize(new { totalNotes = notebook.Notes.Count, notes = notebook.Notes });
     }
 }

 // ---------------------------------------------------------------------------
 // Simple in-memory notebook
 // ---------------------------------------------------------------------------
 sealed class Notebook
 {
     public List<NoteEntry> Notes { get; } = [];

     public void Add(string title, string content) =>
         Notes.Add(new NoteEntry(title, content, DateTime.UtcNow));

     public void Clear() => Notes.Clear();
 }

 record NoteEntry(string Title, string Content, DateTime Timestamp);
